/* ==UserStyle==
@name           Paxos Spec Style
@namespace      http://yourdomain.com
@version        1.0
@description    A style for the Paxos spec page.
@match          https://lamport.eecs.umich.edu/eecs491/projs/p3.html
==/UserStyle== */

/* General body styles */
body {
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  line-height: 1.6;
  margin: 0;
  padding: 20px;
  background-color: #f5f5f5;
  color: #333;
}

/* Center the main container and limit width */
div {
  margin: 0 auto;
  max-width: 800px;
  padding: 0 10px;
}

/* Headings styles */
h1 {
  font-size: 2.5em;
  text-align: center;
  margin-bottom: 0.5em;
  color: #222;
}

h3 {
  font-size: 1.5em;
  margin-bottom: 0.75em;
  color: #222;
}

/* Paragraph styles */
p {
  margin-bottom: 1em;
  text-align: justify;
}

/* Horizontal rule styling */
hr {
  border: none;
  height: 1px;
  background-color: #ccc;
  margin: 2em 0;
}

/* Code block / preformatted text styling */
pre {
  background-color: #eee;
  padding: 10px;
  overflow-x: auto;
  border-radius: 4px;
  font-family: Consolas, "Courier New", monospace;
}

/* Link styling */
a {
  color: #0066cc;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Image styling */
img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 1em auto;
}
